public boolean hurt(@NotNull DamageSource source, float amount) {
    if (invulnerableTime > 0) {
        return false;
    }
    if (level().isClientSide || isInvulnerableTo(source)) {
        return false;
    }
    if (DamageSources.isFriendlyFireBetween(source.getEntity(), getOwner())) {
        return false;
    }
    health -= amount;
    if (health <= 0) {
        breakChain();
    } else {
        this.playSound(SoundEvents.CHAIN_STEP);
    }
    invulnerableTime = 10;
    return true;
}

protected void onHitEntity(@NotNull EntityHitResult result) {
    super.onHitEntity(result);
    var entity = result.getEntity();
    LivingEntity victim;
    if (entity instanceof LivingEntity livingEntity) {
        victim = livingEntity;
    } else if (entity instanceof PartEntity<?> partEntity && partEntity.getParent() instanceof LivingEntity livingEntity) {
        victim = livingEntity;
    } else {
        victim = null;
    }
    if (!level.isClientSide && victim != null) {
        spawnChainsOnEntity(victim);
    }
    consumeEntityImpact(result, true);
}

protected void onHitBlock(@NotNull BlockHitResult result) {
    super.onHitBlock(result);
    if (!level.isClientSide) {
        Vec3 impactPos = result.getLocation();
        spawnChainsFromBlock(impactPos);
    }
    discard();
}

    private void spawnChainsOnEntity(LivingEntity victim) {
//        Vec3 forward = victim.getForward().yRot(60 * Mth.DEG_TO_RAD);
        Vec3 origin = victim.getBoundingBox().getCenter();

        float theta = Mth.TWO_PI / CHAIN_COUNT;
        for (int i = 0; i < CHAIN_COUNT; i++) {
            float angle = theta * i + Mth.TWO_PI / 4 - getYRot() * Mth.DEG_TO_RAD;
            float radius = lashRadius * 0.5f + victim.getBbWidth() * .4f;
            Vec3 direction = new Vec3(Mth.cos(angle) * radius, 0, Mth.sin(angle) * radius);
            Vec3 worldPos = Utils.moveToRelativeGroundLevel(victim.level, origin.add(direction), 2);
            if (level.noCollision(AABB.ofSize(worldPos, 0.5, 0.5, 0.5))) {
                Vec3 random = Utils.getRandomVec3(2);
                random = random.subtract(direction.scale(direction.normalize().dot(random.normalize())));
                worldPos = origin.add(direction).add(random);
            }
            spawnChain(victim, worldPos);
        }
    }

private void spawnChainsFromBlock(Vec3 impactPos) {
    // reduced radius on block hit
    float effectiveRadius = lashRadius;
    AABB searchBox = new AABB(impactPos, impactPos).inflate(lashRadius);
    List<LivingEntity> entities = level.getEntitiesOfClass(LivingEntity.class, searchBox, entity ->
            (this.canHitEntity(entity) || entity.isMultipartEntity()) && distanceToSqr(entity) < effectiveRadius * effectiveRadius);
    entities.sort(Comparator.comparingDouble(e -> e.distanceToSqr(impactPos)));

    int count = Math.min(CHAIN_COUNT, entities.size());
    for (int i = 0; i < count; i++) {
        spawnChain(entities.get(i), impactPos);
    }
}

private void spawnChain(LivingEntity victim, Vec3 anchor) {
    anchor = Utils.raycastForBlock(victim.level, this.position(), anchor, ClipContext.Fluid.ANY).getLocation();
    EnderChain chain = new EnderChain(level, getOwner(), victim, anchor);
    chain.setHealth(chainHealth);
    chain.setLifetime(chainLifetime);
    chain.setRestraintStrength(restraintStrength);
    level.addFreshEntity(chain);
}

public void tick() {
    super.tick();
    if (invulnerableTime > 0) {
        invulnerableTime--;
    }
    if (warmup < VISUAL_WARMUP_TIME) {
        warmup++;
    }
    if (!level().isClientSide) {
        Entity victim = getVictim();
        if (victim == null || victim.isRemoved() || victim.distanceToSqr(this) > 12 * 12 || tickCount > lifetime || health <= 0) {
            breakChain();
            return;
        }
        applyRestraint(victim);
    } else {
        chainParticlesAround(this.position(), 3);
        if (parts != null && parts.length > 0) {
            chainParticlesAround(parts[parts.length - 1].position(), 1);
        }
    }

    repositionParts();
}

private void applyRestraint(Entity victim) {
    Vec3 displacement = victim.position().subtract(position());
    if (displacement.lengthSqr() < 1.0E-8) {
        return;
    }
    Vec3 deltaV = displacement.scale(-restraintStrength);
    deltaV.multiply(deltaV);
    victim.setDeltaMovement(victim.getDeltaMovement().add(deltaV));
    victim.hurtMarked = true;
    if (victim.getDeltaMovement().y >= 0) {
        victim.resetFallDistance();
    }
}

public void breakChain() {
    if (!level().isClientSide) {
        playSound(SoundEvents.CHAIN_BREAK);
        if (parts.length > 0) {
            int count = 15;
            Vec3 pos = position();
            Vec3 end = parts[parts.length - 1].position();
            for (int i = 0; i < count; i++) {
                Vec3 vec3 = pos.lerp(end, i / (float) count);
                MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, vec3.x, vec3.y, vec3.z, 1, 0.05, 0.05, 0.05, 0.1, false);
            }
        }
        this.discard();
    }
}

public boolean hurt(@NotNull DamageSource source, float amount) {
    if (!level.isClientSide) {
        MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, getBoundingBox().getCenter().x, getBoundingBox().getCenter().y, getBoundingBox().getCenter().z, 3, 0, 0, 0, 0.15, false);
    }
    return parentChain.hurt(source, amount);
}

public void castSpells() {
    float aoe = getAoe();
    int flatAoe = Math.round(aoe);
    BlockPos start = blockPosition().offset(flatAoe * getDirection().getStepX(), 0, flatAoe * getDirection().getStepZ());
    BlockPos end = blockPosition().offset(-flatAoe * getDirection().getStepX(), flatAoe, -flatAoe * getDirection().getStepZ());
    if (isSensitive()) {
        if (age % (Math.max(1, 20 - 2 * getAccelerates())) != 0 && age != 1)
            return;
        for (BlockPos p : BlockPos.betweenClosed(start, end)) {
            p = p.immutable();
            if (!level.isClientSide) {
                resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new
                        BlockHitResult(new Vec3(p.getX(), p.getY(), p.getZ()), Direction.UP, p, false));
            }
            resolveEmitter.setPositionOffset(p.subtract(blockPosition()).getCenter());
            if (level.isClientSide) {
                resolveEmitter.tick(level);
            }
        }
        if (!level.isClientSide) {
            resolveSound.playSound(level, getX(), getY(), getZ());
        }
    } else {
        int i = 0;
        // Expand the axis if start and end are equal

        AABB aabb = AABB.encapsulatingFullBlocks(start, end);
        if (aabb.maxX == aabb.minX) {
            aabb = aabb.inflate(growthFactor, 0, 0);
        }
        if (aabb.maxY == aabb.minY) {
            aabb = aabb.inflate(0, growthFactor, 0);
        }
        if (aabb.maxZ == aabb.minZ) {
            aabb = aabb.inflate(0, 0, growthFactor);
        }
        for (Entity entity : level.getEntities(null, aabb)) {
            if (entity.equals(this) || entity.getType().is(EntityTags.LINGERING_BLACKLIST)) {
                continue;
            }
            Optional<EntityHit> hit = hitEntities.stream().filter(e -> e.entity.refersTo(entity)).findFirst();
            boolean skipEntity = hit.isPresent();
            if (hit.isPresent() && level.getGameTime() - hit.get().gameTime > 20) {
                hitEntities.remove(hit.get());
                skipEntity = false;
            }
            if (skipEntity)
                continue;
            if (!level.isClientSide) {
                resolver().getNewResolver(resolver().spellContext.clone().makeChildContext()).onResolveEffect(level, new EntityHitResult(entity));
            }
            resolveEmitter.setPositionOffset(entity.position.subtract(position).add(0, entity.getBbHeight() / 2.0, 0));
            if (level.isClientSide) {
                resolveEmitter.tick(level);
            }
            i++;
            if (hit.isEmpty()) {
                hitEntities.add(new EntityHit(entity));
            }
            if (i > 5)
                break;
            if (!level.isClientSide) {
                resolveSound.playSound(level, getX(), getY(), getZ());
            }
        }
        totalProcs += i;
        if (totalProcs >= maxProcs)
            this.remove(RemovalReason.DISCARDED);
    }
}

public void onResolve(HitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    Vec3 hit = safelyGetHitPos(rayTraceResult);
    EntityWallSpell entityWallSpell = new EntityWallSpell(world, shooter);
    if (spellContext.getCurrentIndex() >= spellContext.getSpell().size())
        return;

    SpellContext newContext = spellContext.makeChildContext();
    spellContext.setCanceled(true);


    entityWallSpell.setAoe((float) spellStats.getAoeMultiplier());
    entityWallSpell.setSensitive(spellStats.isSensitive());
    entityWallSpell.setAccelerates((int) spellStats.getAccMultiplier());
    entityWallSpell.extendedTime = spellStats.getDurationMultiplier();
    entityWallSpell.setShouldFall(!spellStats.hasBuff(AugmentDampen.INSTANCE));


    Direction facingDirection = spellContext.getCaster().getFacingDirection();
    entityWallSpell.setDirection(facingDirection == UP || facingDirection == DOWN ? facingDirection : facingDirection.getClockWise());
    entityWallSpell.setResolver(resolver.getNewResolver(newContext));
    entityWallSpell.setPos(hit.x, hit.y, hit.z);
    world.addFreshEntity(entityWallSpell);
}

public void tick() {
    if (!level.isClientSide) {
        if (resolver() == null)
            return;
        boolean isOnGround = level.getBlockState(blockPosition()).blocksMotion();

        this.setLanded(isOnGround);
    }
    super.tick();
    castSpells();
}

public void tick() {
    super.tick();
    if (age == 0 && castSound != null && !level.isClientSide) {
        castSound.playSound(level, getX(), getY(), getZ());
    }
    age++;

    if ((!level.isClientSide && this.age > getExpirationTime()) || (!level.isClientSide && resolver() == null)) {
        this.remove(RemovalReason.DISCARDED);
        return;
    }


    this.xOld = this.getX();
    this.yOld = this.getY();
    this.zOld = this.getZ();


    Vec3 thisPosition = this.position();
    Vec3 nextPosition = getNextHitPosition();
    traceAnyHit(getHitResult(), thisPosition, nextPosition);
    if (redirected) {
        redirected = false;
    } else {
        tickNextPosition();
    }

    if (level.isClientSide && this.age >= getParticleDelay()) {
        playParticles();
    }
}

public int getExpirationTime() {
    return (int) (70 + extendedTime * 20);
}

public void buildEmitters() {
    TimelineMap timelineMap = this.resolver().spell.particleTimeline();
    WallTimeline projectileTimeline = timelineMap.get(ParticleTimelineRegistry.WALL_TIMELINE.get());
    TimelineEntryData trailConfig = projectileTimeline.trailEffect;
    TimelineEntryData resolveConfig = projectileTimeline.onResolvingEffect;
    this.tickEmitter = new ParticleEmitter(() -> this.getPosition(ClientInfo.partialTicks), this::getRotationVector, trailConfig.motion(), trailConfig.particleOptions());
    this.resolveEmitter = new ParticleEmitter(() -> this.getPosition(ClientInfo.partialTicks), this::getRotationVector, resolveConfig.motion(), resolveConfig.particleOptions());
    if (this.tickEmitter.particleOptions instanceof PropertyParticleOptions propertyParticleOptions) {
        propertyParticleOptions.map.set(ParticlePropertyRegistry.WALL_PROPERTY.get(), new WallProperty(Math.round(getAoe()), 5, 20, getDirection()));
    }
    this.resolveSound = projectileTimeline.resolveSound.sound;
}

