public static void preventPocketDimensionTeleportation(EntityTeleportEvent event) {
    if (event.getEntity().level instanceof ServerLevel serverLevel && serverLevel.dimension().equals(PocketDimensionManager.POCKET_DIMENSION) && !(event instanceof EntityTeleportEvent.TeleportCommand)) {
        event.setCanceled(true);
    }
}

public static boolean handleSpellTeleport(AbstractSpell spell, Entity entity, Vec3 destination) {
    var event = new SpellTeleportEvent(spell, entity, destination.x, destination.y, destination.z);
    NeoForge.EVENT_BUS.post(event);
    boolean canceled = event.isCanceled();
    if (!canceled) {
        entity.teleportTo(event.getTargetX(), event.getTargetY(), event.getTargetZ());
    }
    return canceled;
}

public SpellTeleportEvent(AbstractSpell spell, Entity entity, double targetX, double targetY, double targetZ) {
    super(entity, targetX, targetY, targetZ);
    this.spell = spell;
}

    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        if (Log.SPELL_DEBUG) {
            IronsSpellbooks.LOGGER.debug("TeleportSpell.onCast isClient:{}, entity:{}, pmd:{}", level.isClientSide, entity, playerMagicData);
        }
        var teleportData = (TeleportData) playerMagicData.getAdditionalCastData();

        Vec3 dest = null;
        if (teleportData != null) {
            var potentialTarget = teleportData.getTeleportTargetPosition();
            if (potentialTarget != null) {
                dest = potentialTarget;
            }
        }

        if (dest == null) {
            dest = findTeleportLocation(level, entity, getDistance(spellLevel, entity));
        }

        PacketDistributor.sendToPlayersTrackingEntityAndSelf(entity, new TeleportParticlesPacket(entity.position(), dest));

        if (entity.isPassenger()) {
            entity.stopRiding();
        }
        Utils.handleSpellTeleport(this, entity, dest);
        entity.resetFallDistance();

        playerMagicData.resetAdditionalCastData();

//        level.playSound(null, dest.x, dest.y, dest.z, getCastFinishSound().get(), SoundSource.NEUTRAL, 1f, 1f);
        entity.playSound(getCastFinishSound().get(), 2.0f, 1.0f);

        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

