public static void handleClientboundTeleport(Vec3 pos1, Vec3 pos2) {
    var player = Minecraft.getInstance().player;

    if (player != null) {
        var level = Minecraft.getInstance().player.level;
        TeleportSpell.particleCloud(level, pos1);
        TeleportSpell.particleCloud(level, pos2);
    }
}

public static void particleCloud(Level level, Vec3 pos) {
    if (level.isClientSide) {
        double width = 0.5;
        float height = 1;
        for (int i = 0; i < 55; i++) {
            double x = pos.x + Utils.random.nextDouble() * width * 2 - width;
            double y = pos.y + height + Utils.random.nextDouble() * height * 1.2 * 2 - height * 1.2;
            double z = pos.z + Utils.random.nextDouble() * width * 2 - width;
            double dx = Utils.random.nextDouble() * .1 * (Utils.random.nextBoolean() ? 1 : -1);
            double dy = Utils.random.nextDouble() * .1 * (Utils.random.nextBoolean() ? 1 : -1);
            double dz = Utils.random.nextDouble() * .1 * (Utils.random.nextBoolean() ? 1 : -1);
            level.addParticle(ParticleTypes.PORTAL, true, x, y, z, dx, dy, dz);
        }
    }
}

public boolean hurt(@NotNull DamageSource pSource, float pAmount) {
    return SummonUtil.canSummonTakeDamage(pSource) && super.hurt(pSource, pAmount);
}

public static boolean canSummonTakeDamage(DamageSource source) {
    return source.is(DamageTypeTags.BYPASSES_INVULNERABILITY) || ((source.getEntity() != null) && (source.getEntity() instanceof Player));
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (pSource.getEntity() != null && pSource.getEntity().getType().is(Tags.EntityTypes.BOSSES)) {
        return false;
    }
    setArmorStandFrozen(false);
    return super.hurt(pSource, pAmount);
}

public boolean isInvulnerableTo(DamageSource pSource) {
    return super.isInvulnerableTo(pSource) || pSource.is(DamageTypeTags.IS_FALL);
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (pSource.getDirectEntity() instanceof Projectile projectile) {
        pAmount *= .75f;
    }
    if (tickCount < 10 && pSource.is(DamageTypes.IN_WALL)) {
        Utils.doMobBreakSuffocatingBlocks(this);
    }

    return super.hurt(pSource, pAmount);
}

public static void handleCastErrorMessage(CastErrorPacket packet) {
    var spell = SpellRegistry.getSpell(packet.spellId);
    if (packet.errorType == CastErrorPacket.ErrorType.COOLDOWN) {
        //ignore cooldown message if we are simply holding right click.
        if (ClientInputEvents.hasReleasedSinceCasting) {
            Minecraft.getInstance().gui.setOverlayMessage(Component.translatable("ui.irons_spellbooks.cast_error_cooldown", spell.getDisplayName(Minecraft.getInstance().player)).withStyle(ChatFormatting.RED), false);
        }
    } else {
        Minecraft.getInstance().gui.setOverlayMessage(Component.translatable("ui.irons_spellbooks.cast_error_mana", spell.getDisplayName(Minecraft.getInstance().player)).withStyle(ChatFormatting.RED), false);
    }
}

