public static AbstractRitual registerRitual(AbstractRitual ritual) {
    return ritualMap.put(ritual.getRegistryName(), ritual);
}

public static @Nullable AbstractRitual getRitual(ResourceLocation id) {
    if (!ritualMap.containsKey(id))
        return null;
    try {
        return ritualMap.get(id).getClass().getDeclaredConstructor().newInstance();
    } catch (Exception e) {
        e.printStackTrace();
    }
    return null;
}

public void setRitual(ResourceLocation selectedRitual) {
    this.ritual = RitualRegistry.getRitual(selectedRitual);
    if (ritual != null) {
        this.ritual.tile = this;
        Level world = getLevel();
        BlockState state = world.getBlockState(getBlockPos());
        world.setBlock(getBlockPos(), state.setValue(RitualBrazierBlock.LIT, true), 3);
    }
    this.isDecorative = false;
    level.playSound(null, getBlockPos(), SoundEvents.FLINTANDSTEEL_USE, SoundSource.NEUTRAL, 1.0f, 1.0f);
    updateBlock();
}

