package com.hollingsworth.arsnouveau.common.block;


import net.minecraft.core.BlockPos;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.state.BlockState;

/**
 * Interface for tickable things.
 */
public interface ITickable {
    /**
     * Tick the tickable with parameters.
     *
     * @param level the world its ticking in.
     * @param state its state.
     * @param pos   the position its ticking at.
     */
    default void tick(final Level level, final BlockState state, final BlockPos pos) {
        tick();
    }

    /**
     * Default parameterless ticking implementation.
     */
    default void tick() {

    }
}

public void tick() {
    if (isDecorative && level.isClientSide) {
        makeParticle(color.nextColor((int) level.getGameTime() * 20), color.nextColor((int) level.getGameTime() * 20 + 200), 10);
        return;
    }


    if (level.isClientSide && ritual != null) {
        makeParticle(ritual.getCenterColor(), ritual.getOuterColor(), ritual.getParticleIntensity());
    }
    if (isOff)
        return;
    if (ritual != null) {

        if (ritual.getContext().isDone) {
            ritual.onEnd();
            ritual = null;
            getLevel().playSound(null, getBlockPos(), SoundEvents.FIRE_EXTINGUISH, SoundSource.NEUTRAL, 1.0f, 1.0f);
            getLevel().setBlock(getBlockPos(), getLevel().getBlockState(getBlockPos()).setValue(RitualBrazierBlock.LIT, false), 3);
            updateBlock();
            return;
        }
        if (!ritual.isRunning() && !level.isClientSide && level.getGameTime() % 5 == 0) {
            level.getEntitiesOfClass(ItemEntity.class, new AABB(getBlockPos()).inflate(1)).forEach(i -> {
                tryBurnStack(i.getItem());
            });
        }
        if (ritual.consumesSource() && ritual.needsSourceNow()) {
            if (this.sourceBackoff-- <= 0) {
                int cost = ritual.getSourceCost();
                if (SourceUtil.takeSourceMultipleWithParticles(getBlockPos(), getLevel(), 6, cost) != null) {
                    ritual.setNeedsSource(false);
                    this.sourceBackoff = 0;
                    updateBlock();
                } else {
                    this.sourceBackoff = 20;
                    return;
                }
            } else {
                return;
            }
        }
        if (this.relayPos != null && level.isLoaded(this.relayPos) && level.getBlockEntity(this.relayPos) instanceof BrazierRelayTile relayTile) {
            ritual.tryTick(relayTile);
            relayTile.ticksToLightOff = 2;
            relayTile.isDecorative = false;
        } else {
            ritual.tryTick(this);
        }
    }
}

public void startRitual(@Nullable Player player) {
    if (ritual == null || !ritual.canStart(player) || ritual.isRunning())
        return;
    getLevel().playSound(null, getBlockPos(), SoundEvents.ILLUSIONER_CAST_SPELL, SoundSource.NEUTRAL, 1.0f, 1.0f);
    ritual.onStart(player);
}

public void tryTick(RitualBrazierTile tickingTile) {
    if (tickingTile == null || !getContext().isStarted || getContext().isDone) {
        return;
    }
    this.tile = tickingTile;
    tick();
}

public void onStart(@Nullable Player player) {
    getContext().isStarted = true;
    if (player != null) this.playerUUID = player.getUUID();
}

public boolean isRunning() {
    return getContext().isStarted && !getContext().isDone;
}

protected void tick() {
    Level world = getWorld();
    if (world.isClientSide) {
        BlockPos pos = getPos();

        for (int i = 0; i < 10; i++) {
            Vec3 particlePos = new Vec3(pos.getX(), pos.getY(), pos.getZ()).add(0.5, 0, 0.5);
            particlePos = particlePos.add(ParticleUtil.pointInSphere().multiply(5, 5, 5));
            world.addParticle(ParticleLineData.createData(getCenterColor()),
                    particlePos.x(), particlePos.y(), particlePos.z(),
                    pos.getX() + 0.5, pos.getY() + 1, pos.getZ() + 0.5);
        }
    }

    if (!world.isClientSide && world.getGameTime() % 60 == 0) {
        boolean didWorkOnce = false;
        List<LivingEntity> entityList = world.getEntitiesOfClass(LivingEntity.class, new AABB(getPos()).inflate(5.0),
                (m) -> (m.getClassification(false).equals(MobCategory.MONSTER) || m.getType().is(EntityTags.DISINTEGRATION_WHITELIST)) && !(m instanceof Player));
        for (LivingEntity m : entityList) {
            if (m.getType().is(EntityTags.DISINTEGRATION_BLACKLIST)) {
                continue;
            }
            m.remove(Entity.RemovalReason.DISCARDED);
            if (m.isRemoved()) {

                ParticleUtil.spawnPoof((ServerLevel) world, m.blockPosition());
                if (m.shouldDropExperience()) {
                    int exp = m.getExperienceReward((ServerLevel) world, null) * 2;
                    if (exp > 0) {
                        int numGreater = exp / 12;
                        exp -= numGreater * 12;
                        int numLesser = exp / 3;
                        if ((exp - numLesser * 3) > 0)
                            numLesser++;
                        var pos = m.blockPosition().getBottomCenter();
                        if (numGreater > 0) {
                            world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.GREATER_EXPERIENCE_GEM, numGreater)));
                        }
                        if (numLesser > 0) {
                            world.addFreshEntity(new ItemEntity(world, pos.x, pos.y, pos.z, new ItemStack(ItemsRegistry.EXPERIENCE_GEM, numLesser)));
                        }
                        didWorkOnce = true;
                    }

                }
            }
        }
        if (didWorkOnce)
            setNeedsSource(true);
    }
}

public static void totemEvent(final LivingDeathEvent event) {
    LivingEntity entity = event.getEntity();
    if (!(entity instanceof Player player))
        return;
    var holder = PerkUtil.getHolderForPerk(TotemPerk.INSTANCE, entity);
    if (holder == null)
        return;
    CompoundTag tag = holder.getB().getTagForPerk(TotemPerk.INSTANCE);
    if (tag == null || !tag.getBoolean("isActive")) {
        return;
    }
    entity.setHealth(1.0F);
    entity.removeAllEffects();
    entity.addEffect(new MobEffectInstance(MobEffects.REGENERATION, 900, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.ABSORPTION, 100, 1));
    entity.addEffect(new MobEffectInstance(MobEffects.FIRE_RESISTANCE, 800, 0));
    entity.level.broadcastEntityEvent(entity, (byte) 35);
    tag.putBoolean("isActive", false);
    holder.getA().set(DataComponentRegistry.ARMOR_PERKS, holder.getB().setTagForPerk(TotemPerk.INSTANCE, tag));
    PortUtil.sendMessage(entity, Component.translatable("ars_nouveau.totem_perk.trigger"));
    event.setCanceled(true);
}

public static void sleepEvent(final SleepFinishedTimeEvent event) {
    for (Player p : event.getLevel().players()) {
        var holder = PerkUtil.getHolderForPerk(TotemPerk.INSTANCE, p);
        if (holder == null)
            continue;
        CompoundTag tag = holder.getB().getTagForPerk(TotemPerk.INSTANCE);
        if (tag != null) {
            tag.putBoolean("isActive", true);
            holder.getA().set(DataComponentRegistry.ARMOR_PERKS, holder.getB().setTagForPerk(TotemPerk.INSTANCE, tag));
        }
        PortUtil.sendMessage(p, Component.translatable("ars_nouveau.totem_perk.active"));
    }
}

public @Nullable CompoundTag getTagForPerk(IPerk perk) {
    return this.perkTags.map().getOrDefault(perk, null);
}

public ArmorPerkHolder setTagForPerk(IPerk perk, CompoundTag tag) {
    return new ArmorPerkHolder(color, getPerks(), getTier(), getPerkTags().put(perk, tag));
}

public PerkMap put(IPerk slot, CompoundTag tag) {
    return new PerkMap(Util.copyAndPut(map, slot, tag));
}

package com.hollingsworth.arsnouveau.common.items.data;

import com.hollingsworth.arsnouveau.api.perk.IPerk;
import com.hollingsworth.arsnouveau.api.perk.PerkSlot;
import com.hollingsworth.arsnouveau.api.registry.PerkRegistry;
import com.mojang.serialization.Codec;
import com.mojang.serialization.codecs.RecordCodecBuilder;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.item.DyeColor;
import net.minecraft.world.item.ItemStack;

import java.util.*;

public class ArmorPerkHolder extends StackPerkHolder<ArmorPerkHolder> {

    public static final Codec<ArmorPerkHolder> CODEC = RecordCodecBuilder.create(instance -> instance.group(
            Codec.STRING.fieldOf("color").forGetter(ArmorPerkHolder::getColor),
            StackPerkHolder.PERK_CODEC.listOf().fieldOf("perks").forGetter(ArmorPerkHolder::getPerks),
            Codec.INT.fieldOf("tier").forGetter(ArmorPerkHolder::getTier),
            PerkMap.CODEC.fieldOf("perkTags").forGetter(ArmorPerkHolder::getPerkTags)
    ).apply(instance, ArmorPerkHolder::new));

    private String color;

    public ArmorPerkHolder(String color, List<IPerk> perks, int tier, Map<IPerk, CompoundTag> perkTags) {
        super(perks, tier, perkTags);
        this.color = color;
    }

    public ArmorPerkHolder(String color, List<IPerk> perks, int tier, PerkMap perkTags) {
        super(perks, tier, perkTags);
        this.color = color;
    }

    public ArmorPerkHolder() {
        this("", new ArrayList<>(), 0, new HashMap<>());
    }

    @Deprecated(forRemoval = true) // Use the BASE_COLOR data component
    public String getColor() {
        return color == null ? DyeColor.PURPLE.getName() : color;
    }

    @Deprecated(forRemoval = true) // Use the BASE_COLOR data component
    public ArmorPerkHolder setColor(String color) {
        return new ArmorPerkHolder(color, getPerks(), getTier(), getPerkTags());
    }

    @Override
    public ArmorPerkHolder setPerks(List<IPerk> perks) {
        return new ArmorPerkHolder(color, perks, getTier(), getPerkTags());
    }

    @Override
    public List<PerkSlot> getSlotsForTier(ItemStack stack) {
        List<List<PerkSlot>> slotsForTier = PerkRegistry.getPerkProvider(stack);
        if (slotsForTier == null) {
            return Collections.emptyList();
        }
        List<PerkSlot> slots = new ArrayList<>(slotsForTier.get(getTier()));
        slots.sort(Comparator.comparingInt((a) -> -a.value()));
        return slots;
    }

    @Override
    public ArmorPerkHolder setTier(int tier) {
        return new ArmorPerkHolder(color, getPerks(), tier, getPerkTags());
    }

    @Override
    public ArmorPerkHolder setTagForPerk(IPerk perk, CompoundTag tag) {
        return new ArmorPerkHolder(color, getPerks(), getTier(), getPerkTags().put(perk, tag));
    }

    public ArmorPerkHolder setPerkTags(Map<IPerk, CompoundTag> perkTags) {
        return new ArmorPerkHolder(color, getPerks(), getTier(), perkTags);
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        if (!super.equals(o)) return false;
        ArmorPerkHolder that = (ArmorPerkHolder) o;
        return Objects.equals(color, that.color);
    }

    @Override
    public int hashCode() {
        return Objects.hash(super.hashCode(), color);
    }
}

package com.hollingsworth.arsnouveau.common.items.data;

import com.google.common.collect.ImmutableMap;
import com.hollingsworth.arsnouveau.api.perk.IPerk;
import com.hollingsworth.arsnouveau.api.registry.PerkRegistry;
import com.hollingsworth.arsnouveau.common.perk.StarbunclePerk;
import com.mojang.serialization.Codec;
import net.minecraft.Util;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.resources.ResourceLocation;

import java.util.Map;
import java.util.Objects;

public record PerkMap(Map<IPerk, CompoundTag> map) {
    public static Codec<PerkMap> CODEC = Codec.unboundedMap(Codec.STRING, CompoundTag.CODEC).xmap((stringMap) -> {
        var builder = ImmutableMap.<IPerk, CompoundTag>builder();
        stringMap.forEach((key, value) -> {
            if (key != null) {
                var loc = ResourceLocation.tryParse(key);
                if (loc == null) {
                    return;
                }
                var perk = PerkRegistry.getPerkMap().getOrDefault(loc, StarbunclePerk.INSTANCE);
                builder.put(perk, value);
            }
        });
        return new PerkMap(builder.build());
    }, obj -> {
        var builder = ImmutableMap.<String, CompoundTag>builder();
        obj.map.forEach((key, value) -> builder.put(key.getRegistryName().toString(), value));
        return builder.build();
    });

    public CompoundTag getOrDefault(IPerk slot, CompoundTag tag) {
        return map.getOrDefault(slot, tag);
    }

    public CompoundTag get(IPerk slot) {
        return map.get(slot);
    }

    public PerkMap put(IPerk slot, CompoundTag tag) {
        return new PerkMap(Util.copyAndPut(map, slot, tag));
    }

    @Override
    public boolean equals(Object o) {
        if (this == o) return true;
        if (o == null || getClass() != o.getClass()) return false;
        PerkMap that = (PerkMap) o;
        return Objects.equals(map, that.map);
    }

    @Override
    public int hashCode() {
        return Objects.hashCode(map);
    }

}

